#include <iostream>
#include <string>
#include <utility>
#include <vector>
using namespace std;

struct Tracker {
    string name;
    static int copies;
    explicit Tracker(string n) : name(std::move(n)) {}
    Tracker(const Tracker& o) : name(o.name) { ++copies; }
};
int Tracker::copies = 0;

int main() {
    vector<Tracker> v;
    v.emplace_back("A");          // 原地构造，不产生拷贝
    v.emplace_back("B");

    Tracker::copies = 0;
    for (auto t : v) { (void)t; }               // 值语义：每个元素拷贝一次
    cout << "for (auto t : v)        拷贝次数 = " << Tracker::copies << "\n";

    Tracker::copies = 0;
    for (const auto& t : v) { (void)t; }        // 引用：零拷贝
    cout << "for (const auto& t : v) 拷贝次数 = " << Tracker::copies << "\n";

    Tracker::copies = 0;
    auto copy = v[0];                            // auto 推导为 Tracker，触发拷贝
    cout << "auto copy = v[0]        拷贝次数 = " << Tracker::copies << "\n";
    cout << "结论：想让 auto 绑定引用必须显式写 &，auto 从不推导出引用\n";
    (void)copy;
}
